cssCode:
#container { display: flex; justify-content: center; align-items: center; background: #000; }
.glitch-text {
  font-family: 'Poppins', sans-serif; font-size: 60px; font-weight: 900;
  color: white; text-transform: uppercase; letter-spacing: 5px;
  position: relative;
  text-shadow: 0.05em 0 0 rgba(255,0,127,0.75), -0.025em -0.05em 0 rgba(0,210,255,0.75), 0.025em 0.05em 0 rgba(0,255,204,0.75);
  animation: glitch 1.5s infinite;
}
.glitch-text::before, .glitch-text::after {
  content: 'GLITCH'; position: absolute; top: 0; left: 0; width: 100%; height: 100%; opacity: 0.8;
}
.glitch-text::before { animation: glitch 650ms infinite; color: #ff007f; z-index: -1; }
.glitch-text::after { animation: glitch 375ms infinite; color: #00d2ff; z-index: -2; }

@keyframes glitch {
  0% { transform: translate(0); clip-path: polygon(0 2%, 100% 2%, 100% 5%, 0 5%); }
  20% { clip-path: polygon(0 15%, 100% 15%, 100% 18%, 0 18%); }
  40% { transform: translate(-5px, 5px); clip-path: polygon(0 40%, 100% 40%, 100% 42%, 0 42%); }
  60% { clip-path: polygon(0 60%, 100% 60%, 100% 65%, 0 65%); }
  80% { transform: translate(5px, -5px); clip-path: polygon(0 80%, 100% 80%, 100% 85%, 0 85%); }
  100% { transform: translate(0); clip-path: polygon(0 2%, 100% 2%, 100% 5%, 0 5%); }
}

